/*
 * test_ablate.cpp — Kernel ablation test for 7B correctness
 * ==========================================================
 *
 * Decodes a single token (12605) and compares against
 * /tmp/rwkv_expected_t0.bin (generated by PIP API).
 *
 * Define any of these to fall back to scalar:
 *   ABLATE_LAYER_NORM   — replace AVX2 layer_norm with scalar
 *   ABLATE_GROUP_NORM   — replace AVX2 group_norm with scalar
 *   ABLATE_TIME_SHIFT   — replace AVX2 time_shift with scalar
 *   ABLATE_VEC_MUL      — replace AVX2 vec_mul with scalar
 *   ABLATE_VEC_ADD      — replace AVX2 vec_add with scalar
 *   ABLATE_RELU_SQ      — replace AVX2 relu_sq with scalar
 *   ABLATE_WKV          — replace AVX2 wkv_decode with scalar
 *   ABLATE_K_NORMALIZE  — replace k_normalize with scalar
 *   ABLATE_GEMV         — replace gemv_f16 with naive loop
 *   ABLATE_SPARSE_FFN   — replace gemv_f16_sparse with dense loop
 *
 * Build:
 *   g++ -O3 -march=native -fopenmp -flto -funroll-loops \
 *       -falign-loops=64 -o test_ablate \
 *       test_ablate.cpp ../src/rwkv_lib.cpp ../src/gemm_fp16.cpp \
 *       -I../src -lm -flto
 */

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>

#include <omp.h>
#include <immintrin.h>

#include "rwkv.h"
#include "rwkv_tune.h"
#include "gemv_f16.h"
#include "gemm_fp16.h"

/* ── forward declarations (mirror rwkv_lib.cpp internals) ──────── */
static inline float sigmoid(float x) { return 1.0f / (1.0f + expf(-x)); }
static inline float sum256(const __m256& x) {
    __m128 low128  = _mm256_castps256_ps128(x);
    __m128 high128 = _mm256_extractf128_ps(x, 1);
    __m128 sum128  = _mm_add_ps(low128, high128);
    __m128 shuf    = _mm_movehl_ps(sum128, sum128);
    sum128         = _mm_add_ps(sum128, shuf);
    shuf           = _mm_shuffle_ps(sum128, sum128, _MM_SHUFFLE(1, 1, 1, 1));
    sum128         = _mm_add_ps(sum128, shuf);
    return _mm_cvtss_f32(sum128);
}

/* ── scalar fallback kernels ─────────────────────────────────────── */

#ifdef ABLATE_LAYER_NORM
static void layer_norm(const float *x, float *y, const float *w, const float *b, int D) {
    double sum = 0, sq = 0;
    for (int i = 0; i < D; i++) { sum += x[i]; sq += (double)x[i] * x[i]; }
    float mean = (float)(sum / D);
    float var  = (float)(sq / D) - mean * mean;
    float inv  = 1.0f / sqrtf(var + 1e-5f);
    for (int i = 0; i < D; i++) y[i] = (x[i] - mean) * inv * w[i] + b[i];
}
#endif

#ifdef ABLATE_GROUP_NORM
static void group_norm(const float *x, float *y, const float *w, const float *b,
                        int n_heads, int h_size) {
    for (int h = 0; h < n_heads; h++) {
        const float *xh = x + h * h_size;
        float       *yh = y + h * h_size;
        double sum = 0, sq = 0;
        for (int i = 0; i < h_size; i++) { sum += xh[i]; sq += (double)xh[i] * xh[i]; }
        float mean = (float)(sum / h_size);
        float var  = (float)(sq / h_size) - mean * mean;
        float inv  = 1.0f / sqrtf(var + 64e-5f);
        for (int i = 0; i < h_size; i++)
            yh[i] = (xh[i] - mean) * inv * w[h * h_size + i] + b[h * h_size + i];
    }
}
#endif

#ifdef ABLATE_TIME_SHIFT
static inline void time_shift(const float *x, const float *xx, const float *shift,
                               float *out, int D) {
    for (int i = 0; i < D; i++) out[i] = x[i] + xx[i] * shift[i];
}
#endif

#ifdef ABLATE_VEC_MUL
static inline void vec_mul(float *y, const float *g, int D) {
    for (int i = 0; i < D; i++) y[i] *= g[i];
}
#endif

#ifdef ABLATE_VEC_ADD
static inline void vec_add(float *y, const float *x, int D) {
    for (int i = 0; i < D; i++) y[i] += x[i];
}
#endif

#ifdef ABLATE_RELU_SQ
static inline void relu_sq(float *y, const float *x, int D) {
    for (int i = 0; i < D; i++) { float v = x[i] > 0 ? x[i] : 0; y[i] = v * v; }
}
#endif

#ifdef ABLATE_WKV
static void wkv_decode(const float *r, const float *w, const float *k_, const float *v,
                        const float *kk, const float *a, const float *w0,
                        float *state, float *y, int dim, int n_heads, int h_size) {
    (void)dim;
    for (int h = 0; h < n_heads; h++) {
        float *S   = state + h * h_size * h_size;
        int    off = h * h_size;
        float w_val[64], kka[64];
        for (int i = 0; i < h_size; i++) {
            w_val[i] = expf(-0.606531f * sigmoid(w0[off + i] + w[off + i]));
            kka[i]   = kk[off + i] * a[off + i];
        }
        for (int i = 0; i < h_size; i++) {
            float *Si = S + i * h_size;
            float  vi = v[off + i];
            float sa = 0;
            for (int j = 0; j < h_size; j++) sa -= Si[j] * kk[off + j];
            float result = 0;
            for (int jj = 0; jj < h_size; jj++) {
                float s = Si[jj] * w_val[jj] + vi * k_[off + jj] + sa * kka[jj];
                Si[jj]  = s;
                result += s * r[off + jj];
            }
            y[off + i] = result;
        }
    }
}
#endif

#ifdef ABLATE_K_NORMALIZE
static void k_normalize(float *const k_, const float *const a, float *const kk,
                         const float *const k_k, const float *const k_a,
                         int T, int dim, int n_heads, int h_size) {
    for (int t = 0; t < T; t++) {
        float *kt  = k_ + t * dim;
        const float *at  = a + t * dim;
        float *kkt = kk + t * dim;
        for (int h = 0; h < n_heads; h++) {
            double sum_sq = 0;
            for (int j = 0; j < h_size; j++) {
                int idx = h * h_size + j;
                float val = kt[idx] * k_k[idx];
                kkt[idx]  = val;
                sum_sq   += (double)val * val;
            }
            float inv = 1.0 / sqrt(sum_sq);
            for (int j = 0; j < h_size; j++)
                kkt[h * h_size + j] *= inv;
        }
        for (int i = 0; i < dim; i++)
            kt[i] = kt[i] * (1.0f + (at[i] - 1.0f) * k_a[i]);
    }
}
#endif

#ifdef ABLATE_GEMV
static void gemv_f16_scalar(const float *x, const uint16_t *W, float *y, int M, int N) {
    for (int j = 0; j < N; j++) y[j] = 0;
    for (int i = 0; i < M; i++) {
        float xi = x[i];
        for (int j = 0; j < N; j++)
            y[j] += xi * fp16_to_f32(W[i * N + j]);
    }
}
static void gemv_f16_st_scalar(const float *x, const uint16_t *W, float *y, int M, int N) {
    for (int j = 0; j < N; j++) y[j] = 0;
    for (int i = 0; i < M; i++) {
        float xi = x[i];
        for (int j = 0; j < N; j++)
            y[j] += xi * fp16_to_f32(W[i * N + j]);
    }
}
#endif

#ifdef ABLATE_SPARSE_FFN
static void gemv_f16_sparse_scalar(const float *k_f32, const uint16_t *V, float *y, int M, int N) {
    for (int i = 0; i < M; i++) {
        float ki = k_f32[i];
        if (ki == 0) continue;
        for (int j = 0; j < N; j++)
            y[j] += ki * fp16_to_f32(V[i * N + j]);
    }
}
#endif

/* ── The actual test ─────────────────────────────────────────────── */

int main(int argc, char **argv) {
    setbuf(stdout, NULL);
    omp_set_num_threads(4);
    gemm_fp16_set_num_threads(4);

    const char *path = argc > 1 ? argv[1] : "rwkv7_7b_fp16.bin";
    RWKVWeights *W = rwkv_weights_load(path);
    if (!W) { fprintf(stderr, "Failed to load %s\n", path); return 1; }

    int vocab = rwkv_get_vocab(W);
    int dim   = rwkv_get_dim(W);

    RWKVState *s = rwkv_state_new(W);
    float *logits  = (float *)aligned_alloc(64, vocab * sizeof(float));
    float *expected = (float *)aligned_alloc(64, vocab * sizeof(float));
    int    buf_sz  = 0;
    float *buf     = (float *)aligned_alloc(64, buf_sz * sizeof(float));
    if (!logits || !expected || !buf) { fprintf(stderr, "OOM\n"); return 1; }

    /* warmup */
    for (int i = 0; i < 2; i++)
        rwkv_decode(W, s, 0, logits);

    /* single decode */
    rwkv_state_reset(s);
    int token = 12605;
    rwkv_decode(W, s, token, logits);

    /* print */
    printf("Decode token %d  (dim=%d, vocab=%d)\n", token, dim, vocab);
    printf("logits[0..7]: ");
    for (int i = 0; i < 8; i++) printf("%.3f ", logits[i]);
    printf("\n");

    /* top-5 */
    std::vector<std::pair<float,int>> top(vocab);
    for (int i = 0; i < vocab; i++) top[i] = {logits[i], i};
    std::partial_sort(top.begin(), top.begin()+5, top.end(),
        [](auto &a, auto &b){return a.first > b.first;});
    printf("Top-5: ");
    for (int i = 0; i < 5; i++) printf("%d:%.3f ", top[i].second, top[i].first);
    printf("\n");

    /* compare with PIP ref */
    FILE *ef = fopen("/tmp/rwkv_expected_t0.bin", "rb");
    if (ef) {
        fread(expected, sizeof(float), vocab, ef);
        fclose(ef);

        double maxd = 0, mx = 0, my = 0;
        for (int i = 0; i < vocab; i++) { mx += logits[i]; my += expected[i]; }
        mx /= vocab; my /= vocab;
        double cov=0, vx=0, vy=0;
        int our_top = top[0].second;
        int ref_top = 0;
        for (int i = 1; i < vocab; i++) if (expected[i] > expected[ref_top]) ref_top = i;
        for (int i = 0; i < vocab; i++) {
            double d = fabs((double)logits[i] - (double)expected[i]);
            if (d > maxd) maxd = d;
            double dx = logits[i]-mx, dy = expected[i]-my;
            cov += dx*dy; vx += dx*dx; vy += dy*dy;
        }
        double corr = cov / sqrt(vx*vy);
        printf("vs PIP ref: max_diff=%.4f  corr=%.6f  argmax=%d(ref=%d) %s\n",
               maxd, corr, our_top, ref_top,
               our_top == ref_top ? "MATCH" : "MISMATCH");
    } else {
        printf("No ref file at /tmp/rwkv_expected_t0.bin\n");
    }

    free(buf); free(expected); free(logits);
    rwkv_state_free(s); rwkv_weights_free(W);
    return 0;
}
